// 1. OBTENER PARÁMETROS DE ENTRADA (Del flujo principal)
// Asegúrate de que el nodo anterior traiga los datos del usuario (Modelo, Turno, etc)
let datosEntrada = {};

// Intentamos leer del input directo o buscar el nodo trigger/code anterior
const items = $input.all();
if (items.length > 0) {
  const firstItem = items[0].json;

  // Lógica de normalización de entrada
  if (firstItem.query && typeof firstItem.query === 'string') {
    try {
      datosEntrada = JSON.parse(firstItem.query);
    } catch (e) {
      datosEntrada = { ...firstItem }; 
    }
  } else if (firstItem.query && typeof firstItem.query === 'object') {
    datosEntrada = firstItem.query;
  } else {
    datosEntrada = firstItem;
  }
}

// --- Detectar Día Específico ---
const diaEspecifico = datosEntrada.DiaEspecifico || datosEntrada.diaEspecifico || null;

// 2. OBTENER TIEMPOS DEL SERVICIO (Referencia a nodo externo)
// ⚠️ VERIFICAR NOMBRE DEL NODO: ¿Se llama 'traer-tiempo' en esta sucursal?
const traerTiemposData = $('traer-tiempo').all(); 

let TIEMPO_SERVICIO = 45; // Default

const modeloVehiculo = (datosEntrada.MODELO || datosEntrada.modelo || '').toUpperCase().trim();

if (modeloVehiculo && traerTiemposData.length > 0) {
  for (const row of traerTiemposData) {
    const rowData = row.json;
    if (rowData[modeloVehiculo]) {
      const tiempoStr = rowData[modeloVehiculo];
      if (typeof tiempoStr === 'string' && tiempoStr.includes(':')) {
        const partes = tiempoStr.split(':');
        const horas = parseInt(partes[0]) || 0;
        const minutos = parseInt(partes[1]) || 0;
        TIEMPO_SERVICIO = (horas * 60) + minutos;
      } 
      else if (tiempoStr) {
         TIEMPO_SERVICIO = parseInt(tiempoStr) || 45;
      }
      break;
    }
  }
}

// 3. PREFERENCIA DE HORARIO
const preferenciaHorario = (datosEntrada.TURNO || datosEntrada.turno || '').toLowerCase().trim();

// 4. FUNCIONES AUXILIARES
const timeToMinutes = (t) => {
  if (!t) return 0;
  if (typeof t === 'number') return t; 
  if (typeof t === 'string' && t.includes(':')) {
    const partes = t.split(':');
    const h = parseInt(partes[0]) || 0;
    const m = parseInt(partes[1]) || 0;
    return h * 60 + m;
  }
  return 0;
};

const minutesToTime = (m) => {
  const h = Math.floor(m / 60).toString().padStart(2, '0');
  const min = (m % 60).toString().padStart(2, '0');
  return `${h}:${min}`;
};

const cruza = (i1, f1, i2, f2) => i1 < f2 && f1 > i2;

const formatearTurno = (fechaObj, minutos) => {
  const diasSemana = ["Domingo", "Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado"];
  const meses = ["01", "02", "03", "04", "05", "06", "07", "08", "09", "10", "11", "12"];

  const diaNombre = diasSemana[fechaObj.getDay()];
  const diaNum = String(fechaObj.getDate()).padStart(2, '0');
  const mesNum = meses[fechaObj.getMonth()];
  const anio = fechaObj.getFullYear();
  const horaStr = minutesToTime(minutos);

  // FORMATO SALIDA: "Lunes 12 de Enero 10:00 - 11:30hs" (Ajustado a tu estilo)
  return `${diaNombre} ${diaNum}/${mesNum}/${anio} ${horaStr}hs`;
};

// 5. OBTENER DATOS EXTERNOS (⚠️ IMPORTANTE: VERIFICAR NOMBRES DE NODOS)
const feriadosData = $('feriados').first()?.json?.feriadosEncontrados || [];

// Nodo de configuración de la sucursal (Horarios, ID Calendario)
const tallerData = $('Get row(s) in sheet').first().json; 

// Nodo que trae los eventos de Google Calendar
const turnosOcupadosRaw = $('Get many events1').all(); 

// 6. EXTRAER Y CALCULAR TIEMPOS (Del Excel de Configuración)
const TIEMPO_RECEPCION = timeToMinutes(tallerData.Recepcion || "00:30:00"); 
const TIEMPO_LAVADO = timeToMinutes(tallerData.Lavado || "00:00:00");
const TIEMPO_ENTREGA = timeToMinutes(tallerData.Entrega || "01:00:00");

const TIEMPO_TOTAL = TIEMPO_RECEPCION + TIEMPO_SERVICIO + TIEMPO_LAVADO + TIEMPO_ENTREGA;

// 7. PROCESAR TURNOS OCUPADOS (ADAPTADO AL CÓDIGO 1)
const ocupados = new Set();

for (const item of turnosOcupadosRaw) {
  // Verificar estructura (Igual que Código 1)
  if (!item || !item.json || !item.json.start || !item.json.start.dateTime) {
    continue; 
  }

  const data = item.json;

  // Extracción robusta (Igual que Código 1)
  const dia = data.start.dateTime.split('T')[0];
  const inicioStr = data.start.dateTime.split('T')[1].substring(0, 5);
  const finalStr = data.end.dateTime.split('T')[1].substring(0, 5);

  if (dia && inicioStr && finalStr) {
    const start = timeToMinutes(inicioStr);
    const end = timeToMinutes(finalStr);

    // Marcar bloques de 15 min como ocupados
    for (let m = start; m < end; m += 15) {
      ocupados.add(`${dia}_${minutesToTime(m)}`);
    }
  }
}

// 8. HORARIOS TALLER
const apertura = timeToMinutes(tallerData["Apertura Mañana"] || tallerData.Apertura || "08:00:00");
const cierre = timeToMinutes(tallerData["Cierre Mañana"] || tallerData.Cierre || "17:30:00");
const iniAlm = timeToMinutes(tallerData["Inicio Almuerzo"] || "13:00:00");
const finAlm = timeToMinutes(tallerData["Fin Almuerzo"] || "14:00:00");

// 9. DEFINIR RANGOS SEGÚN PREFERENCIA
let rangoInicio, rangoFin;

if (preferenciaHorario === 'mañana') {
  rangoInicio = apertura;
  rangoFin = Math.min(iniAlm, cierre);
} else if (preferenciaHorario === 'tarde') {
  rangoInicio = finAlm;
  rangoFin = cierre;
} else {
  rangoInicio = apertura;
  rangoFin = cierre;
}

// 10. BÚSQUEDA DE TURNOS
const feriados = new Set(feriadosData);
const turnosPorDia = new Map(); 

const ahora = new Date(); 
// Ajuste zona horaria manual si es necesario, o confiar en sistema
const minutosAhora = ahora.getHours() * 60 + ahora.getMinutes();
const hoyStr = ahora.toISOString().split('T')[0];

let fecha = new Date();
let diasBuscados = 0;
let MAX_DIAS = 30; 

// Lógica de fecha inicial
if (diaEspecifico) {
  const partes = diaEspecifico.split('-'); // Espera YYYY-MM-DD
  fecha = new Date(partes[0], partes[1] - 1, partes[2]);
  MAX_DIAS = 1; 
} else {
  // Si no hay fecha específica, empezamos mañana
  fecha.setDate(fecha.getDate() + 1);
}

while (diasBuscados < MAX_DIAS) {
  const fechaStr = fecha.toISOString().split('T')[0];
  const diaSemana = fecha.getDay();

  // Lunes(1) a Viernes(5) y no feriado
  if (diaSemana >= 1 && diaSemana <= 5 && !feriados.has(fechaStr)) {
    const turnosDia = [];

    // Iterar cada 15 mins
    for (let hora = rangoInicio; hora + TIEMPO_TOTAL <= rangoFin; hora += 15) {

      // Si es hoy, filtrar horas pasadas
      if (fechaStr === hoyStr && hora < minutosAhora) {
        continue; 
      }

      const finTotal = hora + TIEMPO_TOTAL;

      // Chequear colisión con almuerzo
      if (cruza(hora, finTotal, iniAlm, finAlm)) continue;

      // Chequear colisión con ocupados
      let bloqueado = false;
      for (let m = hora; m < finTotal; m += 15) {
        if (ocupados.has(`${fechaStr}_${minutesToTime(m)}`)) {
          bloqueado = true;
          break;
        }
      }

      if (!bloqueado) {
        // Formato final de hora fin
        const horaFinStr = minutesToTime(finTotal);

        turnosDia.push({
          dia: fechaStr,
          inicio: minutesToTime(hora),
          final: horaFinStr,
          // Texto amigable para el chat
          opcionTexto: `${formatearTurno(fecha, hora)} - ${horaFinStr}hs`,
          // Datos técnicos
          Id_Calendario: tallerData.Id_Calendario,
          minutos: hora,
          tiempoTotal: TIEMPO_TOTAL
        });
      }
    }

    if (turnosDia.length > 0) {
      turnosPorDia.set(fechaStr, turnosDia);
    }
  }

  fecha.setDate(fecha.getDate() + 1);
  diasBuscados++;

  // Si encontramos suficientes días con opciones y no es fecha específica, paramos
  if (!diaEspecifico && turnosPorDia.size >= 10) break;
}

// 11. SELECCIONAR TURNOS VARIADOS (Top 10)
const turnosDisponibles = [];
const diasConTurnos = Array.from(turnosPorDia.keys());

for (let i = 0; i < diasConTurnos.length && turnosDisponibles.length < 10; i++) {
  const dia = diasConTurnos[i];
  const turnosDia = turnosPorDia.get(dia);

  if (turnosDia.length === 1) {
    turnosDisponibles.push(turnosDia[0]);
  } else if (turnosDia.length === 2) {
    turnosDisponibles.push(turnosDia[0], turnosDia[1]);
  } else {
    // Tomar primero, medio y último para variedad
    turnosDisponibles.push(turnosDia[0]);
    if (turnosDisponibles.length < 10) {
      const medio = Math.floor(turnosDia.length / 2);
      turnosDisponibles.push(turnosDia[medio]);
    }
    if (turnosDisponibles.length < 10 && turnosDia.length > 2) {
      turnosDisponibles.push(turnosDia[turnosDia.length - 1]);
    }
  }
}

// 12. FORMATO DE SALIDA COMPATIBLE
return turnosDisponibles.map(t => {
  const { minutos, ...resto } = t;
  return { json: resto };
});

// 1. OBTENER PARÁMETROS DE ENTRADA
const incoming = $('When Executed by Another Workflow').first().json;
let datosEntrada = {};

// Normalización de entrada
if (incoming.query && typeof incoming.query === 'string') {
  try {
    datosEntrada = JSON.parse(incoming.query);
  } catch (e) {
    datosEntrada = { ...incoming }; 
  }
} else if (incoming.query && typeof incoming.query === 'object') {
  datosEntrada = incoming.query;
} else {
  datosEntrada = incoming;
}

// --- NUEVO: DETECTAR DIA ESPECIFICO ---
const diaEspecifico = datosEntrada.DiaEspecifico || datosEntrada.diaEspecifico || null;
// --------------------------------------

// 2. OBTENER TIEMPOS DEL SERVICIO SEGÚN MODELO
const traerTiemposData = $('traer-tiempo').all();

// Default a 45 minutos
let TIEMPO_SERVICIO = 45; 

const modeloVehiculo = (datosEntrada.MODELO || datosEntrada.modelo || '').toUpperCase().trim();

if (modeloVehiculo && traerTiemposData.length > 0) {
  for (const row of traerTiemposData) {
    const rowData = row.json;

    if (rowData[modeloVehiculo]) {
