        const minutos = parseInt(partes[1]) || 0;
        TIEMPO_SERVICIO = (horas * 60) + minutos;
      } 
      else if (tiempoStr) {
         TIEMPO_SERVICIO = parseInt(tiempoStr) || 45;
      }
      break;
    }
  }
}

// 3. PREFERENCIA DE HORARIO (mañana/tarde)
const preferenciaHorario = (datosEntrada.TURNO || datosEntrada.turno || '').toLowerCase().trim();

// 4. FUNCIONES AUXILIARES
const timeToMinutes = (t) => {
  if (!t) return 0;
  if (typeof t === 'number') return t; 

  if (typeof t === 'string' && t.includes(':')) {
    const partes = t.split(':');
    const h = parseInt(partes[0]) || 0;
    const m = parseInt(partes[1]) || 0;
    return h * 60 + m;
  }
  return 0;
};

const minutesToTime = (m) => {
  const h = Math.floor(m / 60).toString().padStart(2, '0');
  const min = (m % 60).toString().padStart(2, '0');
  return `${h}:${min}`;
};

const cruza = (i1, f1, i2, f2) => i1 < f2 && f1 > i2;

const formatearTurno = (fechaObj, minutos) => {
  const diasSemana = ["Domingo", "Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado"];
  const diaNombre = diasSemana[fechaObj.getDay()];
  const diaNum = String(fechaObj.getDate()).padStart(2, '0');
  const mesNum = String(fechaObj.getMonth() + 1).padStart(2, '0');
  const anio = fechaObj.getFullYear();
  const horaStr = minutesToTime(minutos);
  return `${diaNombre} ${diaNum}/${mesNum}/${anio} a las ${horaStr}hs`;
};

// 5. OBTENER DATOS EXTERNOS
const feriadosData = $('feriados').first()?.json?.feriadosEncontrados || [];
const tallerData = $('Get row(s) in sheet').first().json;
const turnosOcupadosRaw = $('Get many events1').all(); 

// 6. EXTRAER Y CALCULAR TIEMPOS
const TIEMPO_RECEPCION = timeToMinutes(tallerData.Recepcion || "00:30:00"); 
const TIEMPO_LAVADO = timeToMinutes(tallerData.Lavado || "00:00:00");
const TIEMPO_ENTREGA = timeToMinutes(tallerData.Entrega || "01:00:00");

const TIEMPO_TOTAL = TIEMPO_RECEPCION + TIEMPO_SERVICIO + TIEMPO_LAVADO + TIEMPO_ENTREGA;

// 7. PROCESAR TURNOS OCUPADOS
const ocupados = new Set();
turnosOcupadosRaw.forEach(item => {
  const t = item.json;
  const dia = t?.start?.dateTime?.split('T')[0] || t?.start?.date;
  const iniStr = t?.start?.dateTime?.split('T')[1]?.slice(0,5);
  const finStr = t?.end?.dateTime?.split('T')[1]?.slice(0,5);

  if (dia && iniStr && finStr) {
    const start = timeToMinutes(iniStr);
    const end = timeToMinutes(finStr);
    for (let m = start; m < end; m += 15) {
      ocupados.add(`${dia}_${minutesToTime(m)}`);
    }
  }
});

// 8. HORARIOS TALLER
const apertura = timeToMinutes(tallerData["Apertura Mañana"] || tallerData.Apertura || "08:00:00");
const cierre = timeToMinutes(tallerData["Cierre Mañana"] || tallerData.Cierre || "17:30:00");
const iniAlm = timeToMinutes(tallerData["Inicio Almuerzo"] || "13:00:00");
const finAlm = timeToMinutes(tallerData["Fin Almuerzo"] || "14:00:00");

// 9. DEFINIR RANGOS SEGÚN PREFERENCIA
let rangoInicio, rangoFin;

if (preferenciaHorario === 'mañana') {
  rangoInicio = apertura;
  rangoFin = Math.min(iniAlm, cierre);
} else if (preferenciaHorario === 'tarde') {
  rangoInicio = finAlm;
  rangoFin = cierre;
} else {
  rangoInicio = apertura;
  rangoFin = cierre;
}

// 10. BÚSQUEDA DE TURNOS (MODIFICADO PARA USAR FECHA ESPECÍFICA)
const feriados = new Set(feriadosData);
const turnosDisponibles = [];
const turnosPorDia = new Map();

const ahora = new Date(); 
const minutosAhora = ahora.getHours() * 60 + ahora.getMinutes();
const hoyStr = ahora.toISOString().split('T')[0];

let fecha = new Date();
let diasBuscados = 0;
let MAX_DIAS = 30; // Default: buscar en ventana de 30 días

// --- LÓGICA CLAVE CORREGIDA ---
if (diaEspecifico) {
  // CASO A: SI LLEGA FECHA ESPECÍFICA (YYYY-MM-DD)
  const partes = diaEspecifico.split('-'); // [YYYY, MM, DD]
  // Crear fecha (Mes es 0-indexado)
  fecha = new Date(partes[0], partes[1] - 1, partes[2]);

  // IMPORTANTE: Forzar búsqueda de UN SOLO DÍA
  MAX_DIAS = 1; 

} else if (datosEntrada.fecha_inicio) {
  // CASO B: Legacy
  const partes = datosEntrada.fecha_inicio.split('-');
  if (partes.length === 3) {
    const [yyyy, mm, dd] = partes.map(Number);
    fecha = new Date(yyyy, mm - 1, dd); 
  } else {
    fecha.setDate(fecha.getDate() + 1);
  }
} else {
  // CASO C: Automático (Empezar mañana)
  fecha.setDate(fecha.getDate() + 1);
}
// ------------------------------

while (diasBuscados < MAX_DIAS) {
  const fechaStr = fecha.toISOString().split('T')[0];
  const diaSemana = fecha.getDay();

  // Validar si es día hábil (Lunes a Viernes) y no es feriado
  if (diaSemana >= 1 && diaSemana <= 5 && !feriados.has(fechaStr)) {
    const turnosDia = [];

    for (let hora = rangoInicio; hora + TIEMPO_TOTAL <= rangoFin; hora += 15) {

      // Si estamos buscando en el día de HOY, validar que la hora no haya pasado
      if (fechaStr === hoyStr && hora < minutosAhora) {
        continue; 
      }

      const finTotal = hora + TIEMPO_TOTAL;

      if (cruza(hora, finTotal, iniAlm, finAlm)) continue;

      let bloqueado = false;
      for (let m = hora; m < finTotal; m += 15) {
        if (ocupados.has(`${fechaStr}_${minutesToTime(m)}`)) {
          bloqueado = true;
          break;
        }
      }

      if (!bloqueado) {
        turnosDia.push({
          dia: fechaStr,
          inicio: minutesToTime(hora),
          final: minutesToTime(finTotal),
          opcionTexto: formatearTurno(fecha, hora),
          Id_Calendario: tallerData.Id_Calendario,
          minutos: hora,
          tiempoTotal: TIEMPO_TOTAL,
          desglose: {
            recepcion: TIEMPO_RECEPCION,
            servicio: TIEMPO_SERVICIO,   
            lavado: TIEMPO_LAVADO,       
            entrega: TIEMPO_ENTREGA      
          }
        });
      }
    }

    if (turnosDia.length > 0) {
      turnosPorDia.set(fechaStr, turnosDia);
    }
  }

